import { useContext } from 'react';

import { ViewProviderContext } from './view-provider.context';

export const useViewProvider = () => {
  const context = useContext(ViewProviderContext);
  if (!context) {
    throw new Error('useViewProvider must be used within a ViewProvider');
  }

  return context;
};
