import { useMemo } from 'react';

import { EventProviderContext } from './event-provider.context';
import { EventProviderProps } from './event-provider.types';

export const EventProvider = ({
  children,
  onTestCaseClick,
}: EventProviderProps) => {
  const value = useMemo(
    () => ({
      onTestCaseClick,
    }),
    [onTestCaseClick],
  );

  return (
    <EventProviderContext.Provider value={value}>
      {children}
    </EventProviderContext.Provider>
  );
};
