import { cn } from '@heal/front-core/lib/utils';
import { TraceViewerActionBlock } from '@heal/front-core/ui';
import { useEffect, useMemo, useRef } from 'react';

import { useDataProvider } from '../../../../context/data-provider/data-provider.hooks';
import { useStatementProvider } from '../../../../context/statement-provider/statement-provider.hooks';
import { Statement } from '../../../../types/test';
import { formatDuration } from '../../../../utils/format-duration';

import { mapStatementStatusToStepCardStatus } from './code-view';
import { EmptyState } from './empty-state';

function countStatements(statements: Statement[]): {
  passed: number;
  failed: number;
  total: number;
} {
  let passed = 0;
  let failed = 0;

  function walk(stmts: Statement[]) {
    for (const s of stmts) {
      if (s.comment) {
        if (s.status === 'passed') {
          passed++;
        } else {
          failed++;
        }
      }
      walk(s.children);
    }
  }

  walk(statements);

  return { passed, failed, total: passed + failed };
}

export const ActionView = () => {
  const { currentTest } = useDataProvider();

  const counts = useMemo(
    () => (currentTest ? countStatements(currentTest.statements) : null),
    [currentTest],
  );

  if (!currentTest || !counts) {
    return <EmptyState />;
  }

  return (
    <div className="flex h-full flex-1 flex-col overflow-auto p-3">
      <div className="flex shrink-0 items-center gap-2 px-3 pb-2 text-xs text-muted-foreground">
        <span>{counts.total} steps</span>
        <span className="text-muted-foreground/40">·</span>
        <span className="text-success-solid">{counts.passed} passed</span>
        {counts.failed > 0 && (
          <>
            <span className="text-muted-foreground/40">·</span>
            <span className="text-danger-solid">{counts.failed} failed</span>
          </>
        )}
      </div>
      <div className="flex flex-1 flex-col gap-1.5 overflow-auto p-3">
        {currentTest.statements.map((statement) => (
          <ActionItem key={statement.code} statement={statement} />
        ))}
      </div>
    </div>
  );
};

function ActionItem({
  statement,
  nestedLevel = 0,
}: {
  statement: Statement;
  nestedLevel?: number;
}) {
  const { activeStatement, setActiveStatementId } = useStatementProvider();
  const ref = useRef<HTMLDivElement>(null);
  const isActive = activeStatement?.id === statement.id;

  useEffect(() => {
    if (isActive && ref.current) {
      ref.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [isActive]);

  if (!statement.comment) {
    return null;
  }

  function handleSelectStatement() {
    if (activeStatement?.id === statement.id) {
      setActiveStatementId(null);

      return;
    }

    setActiveStatementId(statement.id);
  }

  return (
    <div
      ref={ref}
      className={cn(
        'flex flex-col gap-1.5',
        nestedLevel > 0 && 'ml-4 border-l-2 border-muted pl-3',
      )}
    >
      <TraceViewerActionBlock
        key={statement.code}
        status={mapStatementStatusToStepCardStatus(statement.status)}
        duration={formatDuration(statement.durationMs)}
        selected={false}
        active={activeStatement?.id === statement.id}
        onClick={handleSelectStatement}
        screenshotUrl={statement.screenshot ?? undefined}
        {...splitComment(statement.comment ?? '')}
      />
      {statement.children.map((child) => (
        <ActionItem
          key={child.code}
          statement={child}
          nestedLevel={nestedLevel + 1}
        />
      ))}
    </div>
  );
}

const ACTION_VERBS = [
  'Navigate to',
  'Navigates to',
  'Click on',
  'Clicks on',
  'Click',
  'Clicks',
  'Fill in',
  'Fills in',
  'Fill',
  'Fills',
  'Type in',
  'Types in',
  'Type',
  'Types',
  'Wait for',
  'Waits for',
  'Select',
  'Selects',
  'Search for',
  'Searches for',
  'Submit',
  'Submits',
  'Scroll to',
  'Scrolls to',
  'Scroll',
  'Scrolls',
  'Upload',
  'Uploads',
  'Download',
  'Downloads',
  'Open',
  'Opens',
  'Close',
  'Closes',
  'Hover',
  'Hovers',
  'Check',
  'Checks',
  'Uncheck',
  'Unchecks',
  'Accept',
  'Accepts',
  'Dismiss',
  'Dismisses',
  'Verify',
  'Verifies',
  'Assert',
  'Asserts',
  'Expect',
  'Expects',
];

function splitComment(comment: string): { action: string; target: string } {
  const cleaned = comment.replace(/^-+\s*|\s*-+$/g, '').trim();

  const lowerCleaned = cleaned.toLowerCase();
  for (const verb of ACTION_VERBS) {
    if (lowerCleaned.startsWith(verb.toLowerCase() + ' ')) {
      return {
        action: verb,
        target: cleaned.slice(verb.length + 1),
      };
    }
  }

  const [action, ...rest] = cleaned.split(' ');

  return { action, target: rest.join(' ') };
}
