import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type MouseEvent,
} from 'react';

import { cn } from '../../../../../lib/utils';

export type SegmentStatus = 'pass' | 'fail' | 'running' | 'pending' | 'skipped';

export interface TimelineSegment {
  /** Unique segment identifier */
  id: string;
  /** Start time in milliseconds */
  startMs: number;
  /** End time in milliseconds */
  endMs: number;
  /** Segment status (determines color) */
  status: SegmentStatus;
  /** Step label (e.g. "Navigate to login") */
  label?: string;
}

export interface VideoTimelineClassNames {
  /** Root wrapper */
  root?: string;
  /** Segment bar */
  bar?: string;
  /** Labels row */
  labels?: string;
}

export interface VideoTimelineProps {
  /** Total duration in ms */
  durationMs: number;
  /** Current playback position in ms */
  currentTimeMs: number;
  /** Buffered percentage (0-100) */
  bufferedPercent?: number;
  /** Segments to render */
  segments?: TimelineSegment[];
  /** Currently active segment id */
  activeSegmentId?: string;
  /** Callback when user seeks */
  onSeek?: (timeMs: number) => void;
  /** Callback when a segment is clicked */
  onSegmentClick?: (id: string) => void;
  /** Whether to show compact view (no labels) */
  compact?: boolean;
  /** Video source URL for thumbnail preview on hover */
  videoSrc?: string;
  /** Style overrides */
  classNames?: VideoTimelineClassNames;
}

const SEGMENT_EDGE: Record<SegmentStatus, string> = {
  pass: 'bg-success-solid',
  fail: 'bg-danger-solid',
  running: 'bg-info-solid',
  pending: 'bg-neutral-solid',
  skipped: 'bg-neutral-solid',
};

const SEGMENT_FILL: Record<SegmentStatus, string> = {
  pass: 'bg-success-subtle hover:bg-success-subtle-hover',
  fail: 'bg-danger-subtle hover:bg-danger-subtle-hover',
  running: 'bg-info-subtle hover:bg-info-subtle-hover',
  pending: 'bg-muted hover:bg-muted-foreground/15',
  skipped: 'bg-muted hover:bg-muted-foreground/15',
};

const SEGMENT_FILL_ACTIVE: Record<SegmentStatus, string> = {
  pass: 'bg-success-subtle-hover',
  fail: 'bg-danger-subtle-hover',
  running: 'bg-info-subtle-hover',
  pending: 'bg-muted-foreground/15',
  skipped: 'bg-muted-foreground/15',
};

const PREVIEW_WIDTH = 160;
const PREVIEW_HEIGHT = 90;

const formatShortTime = (ms: number): string => {
  const totalSeconds = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;

  return `${minutes}:${String(seconds).padStart(2, '0')}`;
};

export const VideoTimeline = ({
  durationMs,
  currentTimeMs,
  bufferedPercent = 0,
  segments,
  activeSegmentId,
  onSeek,
  onSegmentClick,
  compact = false,
  videoSrc,
  classNames,
}: VideoTimelineProps) => {
  const barRef = useRef<HTMLDivElement>(null);
  const previewVideoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [hoveredSegmentId, setHoveredSegmentId] = useState<string | null>(null);
  const [segmentTooltipPos, setSegmentTooltipPos] = useState<{
    x: number;
    y: number;
  } | null>(null);

  const [hoverTimeMs, setHoverTimeMs] = useState<number | null>(null);
  const [previewPos, setPreviewPos] = useState<{ x: number; y: number } | null>(
    null,
  );

  const progressPercent =
    durationMs > 0 ? (currentTimeMs / durationMs) * 100 : 0;
  const hasSegments = segments && segments.length > 0;
  const hasPreview = Boolean(videoSrc);

  // --- Preview frame capture ---

  useEffect(() => {
    const video = previewVideoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) {
      return;
    }

    const handleSeeked = () => {
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        return;
      }
      ctx.drawImage(video, 0, 0, PREVIEW_WIDTH, PREVIEW_HEIGHT);
    };

    video.addEventListener('seeked', handleSeeked);

    return () => {
      video.removeEventListener('seeked', handleSeeked);
    };
  }, []);

  // --- Seek ---

  const seekToPosition = useCallback(
    (clientX: number) => {
      const bar = barRef.current;
      if (!bar || durationMs === 0) {
        return;
      }
      const rect = bar.getBoundingClientRect();
      const ratio = Math.max(
        0,
        Math.min(1, (clientX - rect.left) / rect.width),
      );
      onSeek?.(ratio * durationMs);
    },
    [durationMs, onSeek],
  );

  const handleMouseDown = useCallback(
    (e: MouseEvent<HTMLDivElement>) => {
      seekToPosition(e.clientX);

      const handleMouseMove = (moveEvent: globalThis.MouseEvent) => {
        seekToPosition(moveEvent.clientX);
      };

      const handleMouseUp = () => {
        document.removeEventListener('mousemove', handleMouseMove);
        document.removeEventListener('mouseup', handleMouseUp);
      };

      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
    },
    [seekToPosition],
  );

  // --- Bar hover (preview) ---

  const handleBarMouseMove = useCallback(
    (e: MouseEvent<HTMLDivElement>) => {
      const bar = barRef.current;
      if (!bar || durationMs === 0) {
        return;
      }
      const rect = bar.getBoundingClientRect();
      const ratio = Math.max(
        0,
        Math.min(1, (e.clientX - rect.left) / rect.width),
      );
      const timeMs = ratio * durationMs;

      setHoverTimeMs(timeMs);
      setPreviewPos({ x: e.clientX, y: rect.top });

      const video = previewVideoRef.current;
      if (video) {
        video.currentTime = timeMs / 1000;
      }
    },
    [durationMs],
  );

  const handleBarMouseLeave = useCallback(() => {
    setHoverTimeMs(null);
    setPreviewPos(null);
  }, []);

  // --- Segment styles ---

  const getSegmentStyle = (segment: TimelineSegment): React.CSSProperties => {
    if (durationMs === 0) {
      return {};
    }
    const leftPct = (segment.startMs / durationMs) * 100;
    const widthPct = ((segment.endMs - segment.startMs) / durationMs) * 100;

    return {
      left: `calc(${leftPct}% + 1px)`,
      width: `calc(${widthPct}% - 2px)`,
    };
  };

  // --- Segment hover (tooltip) ---

  const handleSegmentMouseEnter = (e: MouseEvent, id: string) => {
    setHoveredSegmentId(id);
    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
    setSegmentTooltipPos({ x: rect.left + rect.width / 2, y: rect.top });
  };

  const handleSegmentMouseLeave = () => {
    setHoveredSegmentId(null);
    setSegmentTooltipPos(null);
  };

  const hoveredSegment = segments?.find((s) => s.id === hoveredSegmentId);

  // --- Active segment ---

  const getActiveSegment = () => {
    if (!activeSegmentId || !segments) {
      return null;
    }

    return segments.find((s) => s.id === activeSegmentId) ?? null;
  };

  const activeSegment = getActiveSegment();

  // --- Preview tooltip position (clamped to bar bounds) ---

  const getPreviewLeft = (): number => {
    if (!previewPos || !barRef.current) {
      return 0;
    }
    const barRect = barRef.current.getBoundingClientRect();
    const halfWidth = PREVIEW_WIDTH / 2;
    const minX = barRect.left + halfWidth;
    const maxX = barRect.right - halfWidth;

    return Math.max(minX, Math.min(maxX, previewPos.x));
  };

  return (
    <div className={cn('relative select-none', classNames?.root)}>
      {/* Hidden preview video (loaded once) */}
      {hasPreview && (
        <video
          ref={previewVideoRef}
          src={videoSrc}
          muted
          preload="auto"
          className="hidden"
        />
      )}

      {/* Preview tooltip — always mounted, repositioned via style */}
      {hasPreview && (
        <div
          className={cn(
            'pointer-events-none fixed z-50 -translate-x-1/2 -translate-y-full transition-opacity duration-100',
            hoverTimeMs !== null && previewPos ? 'opacity-100' : 'opacity-0',
          )}
          style={{
            left: hoverTimeMs !== null && previewPos ? getPreviewLeft() : 0,
            top: previewPos ? previewPos.y - 8 : 0,
          }}
        >
          <div className="overflow-hidden rounded-md border bg-surface shadow-lg">
            <canvas
              ref={canvasRef}
              width={PREVIEW_WIDTH}
              height={PREVIEW_HEIGHT}
              className="block"
            />
            <div className="px-2 py-1 text-center text-xs tabular-nums text-muted-foreground">
              {hoverTimeMs !== null ? formatShortTime(hoverTimeMs) : ''}
            </div>
          </div>
        </div>
      )}

      {/* Segment bar */}
      <div
        ref={barRef}
        className={cn(
          'relative cursor-pointer overflow-hidden rounded bg-muted',
          compact ? 'h-4' : 'h-6',
          classNames?.bar,
        )}
        onMouseDown={handleMouseDown}
        onMouseMove={handleBarMouseMove}
        onMouseLeave={handleBarMouseLeave}
      >
        {/* Buffered */}
        <div
          className="absolute inset-y-0 left-0 bg-muted-foreground/10"
          style={{ width: `${bufferedPercent}%` }}
        />

        {/* Segments */}
        {hasSegments &&
          segments.map((segment) => {
            const isActive = segment.id === activeSegmentId;

            return (
              <div
                key={segment.id}
                className={cn(
                  'absolute inset-y-0 flex cursor-pointer transition-colors',
                  isActive
                    ? SEGMENT_FILL_ACTIVE[segment.status]
                    : SEGMENT_FILL[segment.status],
                )}
                style={getSegmentStyle(segment)}
                onClick={(e) => {
                  e.stopPropagation();
                  onSegmentClick?.(segment.id);
                }}
                onMouseEnter={(e) => handleSegmentMouseEnter(e, segment.id)}
                onMouseLeave={handleSegmentMouseLeave}
              >
                <div
                  className={cn(
                    'h-full w-1.5 shrink-0',
                    SEGMENT_EDGE[segment.status],
                  )}
                />
                <div className="flex-1" />
                <div
                  className={cn(
                    'h-full w-1.5 shrink-0',
                    SEGMENT_EDGE[segment.status],
                  )}
                />
              </div>
            );
          })}

        {/* Playhead line */}
        <div
          className="pointer-events-none absolute inset-y-0 w-0.5 bg-foreground"
          style={{ left: `${progressPercent}%` }}
        />
      </div>

      {/* Labels row (expanded only) */}
      {!compact && (
        <div
          className={cn(
            'relative mt-1 flex items-baseline justify-between',
            classNames?.labels,
          )}
        >
          <span className="text-[10px] tabular-nums text-muted-foreground">
            {formatShortTime(0)}
          </span>

          {activeSegment?.label && (
            <span className="truncate px-2 text-xs text-muted-foreground">
              {activeSegment.label}
            </span>
          )}

          <span className="text-[10px] tabular-nums text-muted-foreground">
            {formatShortTime(durationMs)}
          </span>
        </div>
      )}

      {/* Segment tooltip (when no video preview available) */}
      {hoveredSegment && segmentTooltipPos && !hasPreview && (
        <div
          className="pointer-events-none fixed z-50 -translate-x-1/2 -translate-y-full rounded-md border bg-surface px-2.5 py-1.5 shadow-lg"
          style={{ left: segmentTooltipPos.x, top: segmentTooltipPos.y - 6 }}
        >
          <p className="text-xs font-medium text-foreground">
            {hoveredSegment.label ?? hoveredSegment.id}
          </p>
          <p className="mt-0.5 text-[10px] text-muted-foreground">
            {hoveredSegment.status} · {formatShortTime(hoveredSegment.startMs)}{' '}
            → {formatShortTime(hoveredSegment.endMs)}
          </p>
        </div>
      )}
    </div>
  );
};
