import { cva, type VariantProps } from 'class-variance-authority';
import * as React from 'react';

import { Button as ShadcnButton } from '../../../lib/shadcn/button';
import { cn } from '../../../lib/utils';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '../tooltip/tooltip';

// Wraps shadcn button component with Heal styles.

const buttonVariants = cva(
  cn(
    'cursor-pointer border disabled:cursor-not-allowed disabled:pointer-events-auto rounded-sm',
    'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-solid',
    'focus-visible:ring-offset-2 focus-visible:ring-offset-background',
  ),
  {
    variants: {
      variant: {
        important: cn(
          'bg-foreground text-background border-foreground',
          'hover:bg-foreground/90',
          'disabled:text-muted-foreground',
          'disabled:hover:bg-surface-elevated disabled:hover:border-muted',
        ),
        primary: cn(
          'bg-surface-elevated border text-foreground',
          'hover:bg-surface-elevated/90 hover:border',
          'disabled:text-muted-foreground',
          'disabled:hover:bg-surface-elevated disabled:hover:border-muted',
        ),
        secondary: cn(
          'bg-transparent border-muted text-foreground',
          'hover:bg-surface-elevated hover:border-foreground/20',
          'disabled:text-muted-foreground disabled:hover:bg-transparent disabled:hover:border-muted',
        ),
        ghost: cn(
          'bg-transparent border-transparent text-foreground',
          'hover:bg-transparent hover:text-foreground/80',
          'disabled:text-muted-foreground',
        ),
        destructive: cn(
          'bg-danger-solid border-danger-solid text-danger-solid-contrast',
          'hover:bg-danger-solid-hover hover:border-danger-solid-border',
          'disabled:hover:bg-danger-solid disabled:hover:border-danger-solid',
        ),
      },
      size: {
        default: 'h-[28px] px-4 py-2 text-xs',
        sm: 'h-8 rounded-md px-3 text-xs',
        lg: 'h-11 rounded-md px-8 text-base',
        icon: 'h-[28px] w-9 shrink-0 rounded-md p-0',
        iconSm: 'h-6 w-6 shrink-0 rounded p-1',
      },
    },
    defaultVariants: {
      variant: 'primary',
      size: 'default',
    },
  },
);

export interface ButtonProps
  extends
    React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
  /** When set, renders as a toggle: sets aria-pressed and applies on/off visual state. */
  pressed?: boolean;
  /** Optional tooltip shown on hover. When set, the button is wrapped in a Radix tooltip. */
  tooltip?: React.ReactNode;
}

const Button = ({
  className,
  variant,
  size,
  pressed,
  asChild = false,
  tooltip,
  ...props
}: ButtonProps) => {
  const isToggle = pressed !== undefined;
  const toggleClasses =
    isToggle && (pressed ? 'text-foreground' : 'text-muted-foreground');
  const button = (
    <ShadcnButton
      aria-pressed={isToggle ? pressed : undefined}
      asChild={asChild}
      className={cn(
        buttonVariants({ variant, size, className }),
        toggleClasses,
      )}
      {...props}
    />
  );

  if (tooltip !== undefined && tooltip !== null && tooltip !== '') {
    return (
      <TooltipProvider delayDuration={300}>
        <Tooltip>
          <TooltipTrigger asChild>{button}</TooltipTrigger>
          <TooltipContent
            side="top"
            className="max-w-[220px] whitespace-normal wrap-break-word text-xs"
          >
            {tooltip}
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>
    );
  }

  return button;
};

export { Button, buttonVariants };
