import { useCallback, useRef, useState } from 'react';

import { Statement } from '../../types/test';
import { useDataProvider } from '../data-provider/data-provider.hooks';

import { VideoProviderContext } from './video-provider.context';
import { VideoProviderProps } from './video-provider.types';

const flattenStatements = (statements: Statement[]): Statement[] => {
  const result: Statement[] = [];
  for (const statement of statements) {
    result.push(statement);
    if (statement.children.length > 0) {
      result.push(...flattenStatements(statement.children));
    }
  }

  return result;
};

export const VideoProvider = ({ children }: VideoProviderProps) => {
  const { currentTest } = useDataProvider();

  const [currentTimeMs, setCurrentTimeMs] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const seekRef = useRef<((timeMs: number) => void) | null>(null);

  const seekToStatement = useCallback(
    (statementId: number) => {
      if (!currentTest) {
        return;
      }

      const flat = flattenStatements(currentTest.statements);
      const statement = flat.find((s) => s.id === statementId);
      if (!statement) {
        return;
      }

      setCurrentTimeMs(statement.timestampMs);
      seekRef.current?.(statement.timestampMs);
    },
    [currentTest],
  );

  return (
    <VideoProviderContext.Provider
      value={{
        currentTimeMs,
        isPlaying,
        setCurrentTimeMs,
        setIsPlaying,
        seekToStatement,
        seekRef,
      }}
    >
      {children}
    </VideoProviderContext.Provider>
  );
};
