import {
  CheckIcon,
  MaximizeIcon,
  MinimizeIcon,
  PauseIcon,
  PlayIcon,
  SkipBackIcon,
} from 'lucide-react';
import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from 'react';

import { cn } from '../../../../lib/utils';
import { Button } from '../../../components/button/button';

import type {
  TimelineSegment,
  VideoTimelineClassNames,
} from './_components/video-timeline';
import { VideoTimeline } from './_components/video-timeline';

export type {
  SegmentStatus,
  TimelineSegment,
} from './_components/video-timeline';

export interface VideoPlayerClassNames {
  /** Outermost wrapper */
  root?: string;
  /** Video display area */
  video?: string;
  /** Floating controls overlay */
  overlay?: string;
  /** Timeline component */
  timeline?: VideoTimelineClassNames;
  /** Controls bar */
  controls?: string;
}

export interface TraceViewerVideoPlayerProps {
  /** Video source URL */
  src?: string;
  /** Poster image URL */
  poster?: string;
  /** Title displayed above the video (e.g. "REPLAY") */
  title?: ReactNode;
  /** Timeline segments with colored markers */
  segments?: TimelineSegment[];
  /** Currently active segment id (highlighted on timeline) */
  activeSegmentId?: string;
  /** Callback when a segment is clicked */
  onSegmentClick?: (id: string) => void;
  /** Callback when current time changes during playback */
  onTimeUpdate?: (timeMs: number) => void;
  /** Callback when playing state changes */
  onPlayingChange?: (isPlaying: boolean) => void;
  /** Whether to skip inactivity periods. Controlled by parent. */
  skipInactivity?: boolean;
  /** Callback when skip inactivity is toggled */
  onSkipInactivityChange?: (enabled: boolean) => void;
  /** Available playback rates */
  playbackRates?: number[];
  /** Delay in ms before auto-hiding controls (0 to disable). Default: 3000 */
  autoHideDelay?: number;
  /** Style overrides */
  classNames?: VideoPlayerClassNames;
}

const DEFAULT_PLAYBACK_RATES = [0.25, 0.5, 1, 2, 4];
const DEFAULT_AUTO_HIDE_DELAY = 1500;

const formatTime = (ms: number): string => {
  const totalSeconds = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;

  return `${minutes}:${String(seconds).padStart(2, '0')}`;
};

export const TraceViewerVideoPlayer = ({
  src,
  poster,
  title,
  segments,
  activeSegmentId,
  onSegmentClick,
  onTimeUpdate,
  onPlayingChange,
  skipInactivity,
  onSkipInactivityChange,
  playbackRates = DEFAULT_PLAYBACK_RATES,
  autoHideDelay: _autoHideDelay = DEFAULT_AUTO_HIDE_DELAY,
  classNames,
}: TraceViewerVideoPlayerProps) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const hideTimerRef = useRef<ReturnType<typeof setTimeout>>(undefined);

  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTimeMs, setCurrentTimeMs] = useState(0);
  const [durationMs, setDurationMs] = useState(0);
  const [bufferedPercent, setBufferedPercent] = useState(0);
  const [playbackRate, setPlaybackRate] = useState(1);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isCompact, setIsCompact] = useState(true);

  const hasSrc = Boolean(src);

  // --- Controls bar hover: expand on enter, compact on leave ---

  const handleControlsMouseEnter = useCallback(() => {
    clearTimeout(hideTimerRef.current);
    setIsCompact(false);
  }, []);

  const handleControlsMouseLeave = useCallback(() => {
    hideTimerRef.current = setTimeout(() => {
      setIsCompact(true);
    }, 300);
  }, []);

  // Cleanup timer
  useEffect(() => {
    return () => clearTimeout(hideTimerRef.current);
  }, []);

  // --- Video event handlers ---

  const handleTimeUpdate = useCallback(() => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    const timeMs = video.currentTime * 1000;
    setCurrentTimeMs(timeMs);
    onTimeUpdate?.(timeMs);
  }, [onTimeUpdate]);

  const handleLoadedMetadata = useCallback(() => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    setDurationMs(video.duration * 1000);
  }, []);

  const handleProgress = useCallback(() => {
    const video = videoRef.current;
    if (!video || video.buffered.length === 0) {
      return;
    }
    const buffered = video.buffered.end(video.buffered.length - 1);
    setBufferedPercent((buffered / video.duration) * 100);
  }, []);

  const handlePlay = useCallback(() => {
    setIsPlaying(true);
    onPlayingChange?.(true);
  }, [onPlayingChange]);

  const handlePause = useCallback(() => {
    setIsPlaying(false);
    onPlayingChange?.(false);
  }, [onPlayingChange]);

  const handleEnded = useCallback(() => {
    setIsPlaying(false);
    onPlayingChange?.(false);
  }, [onPlayingChange]);

  // --- Control handlers ---

  const handleTogglePlay = useCallback(() => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    if (video.paused || video.ended) {
      video.play();
    } else {
      video.pause();
    }
  }, []);

  const handleRewind = useCallback(() => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    video.currentTime = Math.max(0, video.currentTime - 10);
  }, []);

  const handleSelectPlaybackRate = useCallback((rate: number) => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    video.playbackRate = rate;
    setPlaybackRate(rate);
  }, []);

  const handleToggleFullscreen = useCallback(() => {
    const container = containerRef.current;
    if (!container) {
      return;
    }
    if (document.fullscreenElement) {
      document.exitFullscreen();
    } else {
      container.requestFullscreen();
    }
  }, []);

  const handleToggleSkipInactivity = useCallback(() => {
    onSkipInactivityChange?.(!skipInactivity);
  }, [skipInactivity, onSkipInactivityChange]);

  // --- Timeline seek ---

  const handleSeek = useCallback(
    (timeMs: number) => {
      const video = videoRef.current;
      if (!video) {
        return;
      }
      video.currentTime = timeMs / 1000;
      setCurrentTimeMs(timeMs);
      onTimeUpdate?.(timeMs);
    },
    [onTimeUpdate],
  );

  // --- Fullscreen listener ---

  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(Boolean(document.fullscreenElement));
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);

    return () => {
      document.removeEventListener('fullscreenchange', handleFullscreenChange);
    };
  }, []);

  // --- Keyboard shortcuts ---

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const tag = (e.target as HTMLElement)?.tagName?.toLowerCase();
      if (tag === 'input' || tag === 'textarea' || tag === 'select') {
        return;
      }
      if (e.key === ' ') {
        e.preventDefault();
        handleTogglePlay();
      }
      if (e.key === 'ArrowLeft') {
        e.preventDefault();
        handleRewind();
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [handleTogglePlay, handleRewind]);

  // --- Render ---

  return (
    <div
      ref={containerRef}
      className={cn(
        'relative h-full w-full overflow-hidden bg-black',
        classNames?.root,
      )}
    >
      {/* Video area */}
      <div
        className={cn(
          'flex h-full w-full items-center justify-center',
          classNames?.video,
        )}
        onDoubleClick={handleToggleFullscreen}
        onClick={handleTogglePlay}
      >
        {hasSrc ? (
          <video
            ref={videoRef}
            src={src}
            poster={poster}
            controls={false}
            className="h-full w-full object-contain"
            onTimeUpdate={handleTimeUpdate}
            onLoadedMetadata={handleLoadedMetadata}
            onProgress={handleProgress}
            onPlay={handlePlay}
            onPause={handlePause}
            onEnded={handleEnded}
          />
        ) : (
          <span className="text-sm text-white/40">No video available</span>
        )}
      </div>

      {/* Title overlay */}
      {title && (
        <span className="absolute top-3 left-4 text-xs font-semibold tracking-wider text-white/70">
          {title}
        </span>
      )}

      {/* Floating controls overlay */}
      <div
        className={cn(
          'absolute right-0 bottom-0 left-0 p-3',
          classNames?.overlay,
        )}
        onClick={(e) => e.stopPropagation()}
        onMouseEnter={handleControlsMouseEnter}
        onMouseLeave={handleControlsMouseLeave}
      >
        <div className="overflow-hidden rounded-lg border bg-surface shadow-lg">
          {/* Timeline + compact controls row */}
          <div className="flex items-center gap-2 px-3 pt-2 pb-1.5">
            <div className="flex-1">
              <VideoTimeline
                durationMs={durationMs}
                currentTimeMs={currentTimeMs}
                bufferedPercent={bufferedPercent}
                segments={segments}
                activeSegmentId={activeSegmentId}
                onSeek={handleSeek}
                onSegmentClick={onSegmentClick}
                compact={isCompact}
                videoSrc={src}
                classNames={classNames?.timeline}
              />
            </div>

            {/* Compact play/pause + speed + fullscreen (visible when compact) */}
            <div
              className={cn(
                'flex items-center gap-1 transition-all duration-300',
                isCompact
                  ? 'w-auto opacity-100'
                  : 'pointer-events-none w-0 overflow-hidden opacity-0',
              )}
            >
              <Button
                variant="ghost"
                size="iconSm"
                tooltip={isPlaying ? 'Pause' : 'Play'}
                onClick={handleTogglePlay}
                disabled={!hasSrc}
              >
                {isPlaying ? (
                  <PauseIcon className="size-3.5" />
                ) : (
                  <PlayIcon className="size-3.5" />
                )}
              </Button>
              {playbackRate !== 1 && (
                <span className="rounded bg-foreground/10 px-1.5 py-0.5 text-[10px] font-semibold tabular-nums text-foreground">
                  {playbackRate}x
                </span>
              )}
              <Button
                variant="ghost"
                size="iconSm"
                tooltip={isFullscreen ? 'Exit fullscreen' : 'Fullscreen'}
                onClick={handleToggleFullscreen}
              >
                {isFullscreen ? (
                  <MinimizeIcon className="size-3.5" />
                ) : (
                  <MaximizeIcon className="size-3.5" />
                )}
              </Button>
            </div>
          </div>

          {/* Expanded controls row: slides in/out */}
          <div
            className={cn(
              'grid transition-[grid-template-rows] duration-300 ease-in-out',
              isCompact ? 'grid-rows-[0fr]' : 'grid-rows-[1fr]',
            )}
          >
            <div className="overflow-hidden">
              <div
                className={cn(
                  'flex items-center gap-2 px-3 pb-2',
                  classNames?.controls,
                )}
              >
                <span className="text-sm tabular-nums text-muted-foreground">
                  {formatTime(currentTimeMs)} / {formatTime(durationMs)}
                </span>

                <Button
                  variant="ghost"
                  size="icon"
                  tooltip={isPlaying ? 'Pause' : 'Play'}
                  onClick={handleTogglePlay}
                  disabled={!hasSrc}
                >
                  {isPlaying ? (
                    <PauseIcon className="size-4" />
                  ) : (
                    <PlayIcon className="size-4" />
                  )}
                </Button>

                <Button
                  variant="ghost"
                  size="icon"
                  tooltip="Rewind 10s"
                  onClick={handleRewind}
                  disabled={!hasSrc}
                >
                  <SkipBackIcon className="size-4" />
                </Button>

                <div className="flex items-center gap-1">
                  {playbackRates.map((rate) => (
                    <button
                      key={rate}
                      type="button"
                      disabled={!hasSrc}
                      onClick={() => handleSelectPlaybackRate(rate)}
                      className={cn(
                        'rounded px-2 py-1 text-sm tabular-nums transition-colors',
                        'disabled:pointer-events-none disabled:opacity-40',
                        rate === playbackRate
                          ? 'bg-foreground/10 font-semibold text-foreground'
                          : 'text-muted-foreground hover:text-foreground',
                      )}
                    >
                      {rate}x
                    </button>
                  ))}
                </div>

                <div className="flex-1" />

                {onSkipInactivityChange && (
                  <button
                    type="button"
                    onClick={handleToggleSkipInactivity}
                    className={cn(
                      'flex items-center gap-1.5 rounded px-2 py-1 text-sm transition-colors',
                      skipInactivity
                        ? 'text-success-solid'
                        : 'text-muted-foreground hover:text-foreground',
                    )}
                  >
                    <CheckIcon className="size-3.5" />
                    Skipping Inactivity
                  </button>
                )}

                <Button
                  variant="ghost"
                  size="icon"
                  tooltip={isFullscreen ? 'Exit fullscreen' : 'Fullscreen'}
                  onClick={handleToggleFullscreen}
                >
                  {isFullscreen ? (
                    <MinimizeIcon className="size-4" />
                  ) : (
                    <MaximizeIcon className="size-4" />
                  )}
                </Button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
