import { useEffect, useMemo, useState } from 'react';

import { Statement } from '../../types/test';
import { useDataProvider } from '../data-provider/data-provider.hooks';
import { useVideoProvider } from '../video-provider/video-provider.hooks';

import { StatementProviderContext } from './statement-provider.context';
import { StatementProviderProps } from './statement-provider.types';

const flattenStatements = (statements: Statement[]): Statement[] => {
  const result: Statement[] = [];
  for (const statement of statements) {
    result.push(statement);
    if (statement.children.length > 0) {
      result.push(...flattenStatements(statement.children));
    }
  }

  return result;
};

const findActiveStatement = (
  flatStatements: Statement[],
  timeMs: number,
): Statement | null => {
  for (let i = flatStatements.length - 1; i >= 0; i--) {
    if (timeMs >= flatStatements[i].timestampMs) {
      return flatStatements[i];
    }
  }

  return null;
};

export const StatementProvider = ({ children }: StatementProviderProps) => {
  const { currentTest } = useDataProvider();
  const { currentTimeMs } = useVideoProvider();

  const [selectedStatementId, setSelectedStatementId] = useState<number | null>(
    null,
  );

  const [autoActiveStatement, setAutoActiveStatement] = useState(true);
  const [activeStatementId, setActiveStatementId] = useState<number | null>(
    null,
  );

  const flatStatements = useMemo(() => {
    if (!currentTest) {
      return [];
    }

    return flattenStatements(currentTest.statements);
  }, [currentTest]);

  const selectedStatement = useMemo(() => {
    if (selectedStatementId === null) {
      return null;
    }

    return flatStatements.find((s) => s.id === selectedStatementId) ?? null;
  }, [flatStatements, selectedStatementId]);

  const activeStatement = useMemo(() => {
    if (activeStatementId === null) {
      return null;
    }

    return flatStatements.find((s) => s.id === activeStatementId) ?? null;
  }, [activeStatementId, flatStatements]);

  useEffect(() => {
    if (currentTimeMs && autoActiveStatement) {
      const activeStatement = findActiveStatement(
        flatStatements,
        currentTimeMs,
      );
      if (activeStatement) {
        setActiveStatementId(activeStatement.id);
      }
    }
  }, [currentTimeMs, autoActiveStatement]);

  return (
    <StatementProviderContext.Provider
      value={{
        flatStatements,
        activeStatement,
        activeStatementId,
        selectedStatement,
        selectedStatementId,
        autoActiveStatement,
        setAutoActiveStatement,
        setActiveStatementId,
        setSelectedStatementId,
      }}
    >
      {children}
    </StatementProviderContext.Provider>
  );
};
