import { ImageIcon } from 'lucide-react';

import { TraceViewerContainer } from '../../../../../core/ui/features/trace-viewer';
import { useStatementProvider } from '../../../context/statement-provider/statement-provider.hooks';

export const TEST_SCREENSHOT_VIEW_ID = 'test-screenshot-view';

export const ScreenshotView = () => {
  const { activeStatement } = useStatementProvider();

  return (
    <TraceViewerContainer
      views={[
        {
          id: TEST_SCREENSHOT_VIEW_ID,
          label: 'Screenshot',
          content: activeStatement?.screenshot ? (
            <div className="flex h-full w-full items-center justify-center p-4">
              <img
                src={activeStatement.screenshot}
                alt="Screenshot"
                className="h-full w-full object-contain"
              />
            </div>
          ) : (
            <div className="flex h-full flex-col items-center justify-center gap-3 text-muted-foreground">
              <ImageIcon size={32} className="opacity-60" />
              <span className="text-xs">
                Select a step to view its screenshot
              </span>
            </div>
          ),
        },
      ]}
    />
  );
};
