// Thin wrapper around `@heal-dev/front-run-viewer`'s `<Tracer>` that
// feeds it from the local heal-playwright-tracer server (`/api/*`).
// Mirrors the structure of `apps/web/src/pages/tracer/tracer.tsx`.

import { Tracer } from '@heal-dev/front-run-viewer';
import type { Test, TestList } from '@heal-dev/front-run-viewer';
import { useEffect, useMemo, useState } from 'react';
import { MemoryRouter } from 'react-router';

import {
  fetchExecutions,
  fetchIndex,
  fetchTrace,
  type ExecutionSummary,
} from './api';
import { toTestList, toTracerTest } from './lib/map-trace';

export const App = () => {
  const [executions, setExecutions] = useState<ExecutionSummary[]>([]);
  const [executionsError, setExecutionsError] = useState<string | null>(null);
  const [currentExecutionId, setCurrentExecutionId] = useState<string | null>(
    null,
  );
  const [testList, setTestList] = useState<TestList>([]);
  const [currentTest, setCurrentTest] = useState<Test | null>(null);
  const [indexError, setIndexError] = useState<string | null>(null);
  const [params, setParams] = useState<{
    executionId?: string;
    testId?: string;
    attemptNumber?: number;
  }>({});

  // 1. List executions once on mount and pick the latest as default.
  useEffect(() => {
    let cancelled = false;
    fetchExecutions()
      .then((res) => {
        if (cancelled) return;
        setExecutions(res.executions);
        if (res.executions.length > 0) {
          setCurrentExecutionId(res.executions[0].executionId);
        }
      })
      .catch((err: Error) => {
        if (!cancelled) setExecutionsError(err.message);
      });

    return () => {
      cancelled = true;
    };
  }, []);

  // 2. Whenever the selected execution changes, refetch its index.
  useEffect(() => {
    if (!currentExecutionId) {
      setTestList([]);

      return;
    }
    let cancelled = false;
    setCurrentTest(null);
    setIndexError(null);
    fetchIndex(currentExecutionId)
      .then((res) => {
        if (cancelled) return;
        setTestList(toTestList(currentExecutionId, res.tests));
      })
      .catch((err: Error) => {
        if (!cancelled) setIndexError(err.message);
      });

    return () => {
      cancelled = true;
    };
  }, [currentExecutionId]);

  // 3. Load the selected test's trace whenever the routing params change.
  useEffect(() => {
    if (!currentExecutionId || !params.testId || !params.attemptNumber) {
      setCurrentTest(null);

      return;
    }
    let cancelled = false;
    fetchTrace(currentExecutionId, params.testId, params.attemptNumber)
      .then((trace) => {
        if (cancelled || !params.testId) return;
        setCurrentTest(toTracerTest(trace, params.testId));
      })
      .catch(() => {
        if (!cancelled) {
          setCurrentTest(null);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [currentExecutionId, params.testId, params.attemptNumber]);

  const tracerExecutions = useMemo(
    () =>
      executions.map((e) => ({
        id: e.executionId,
        startedAt: e.startedAt,
        totals: e.totals,
        git: e.git,
      })),
    [executions],
  );

  if (executionsError) {
    return (
      <div className="flex h-full w-full items-center justify-center p-8">
        <div className="max-w-md text-sm text-danger-solid">
          Failed to load executions: {executionsError}
        </div>
      </div>
    );
  }

  if (executions.length === 0) {
    return (
      <div className="flex h-full w-full items-center justify-center p-8">
        <div className="max-w-md text-sm text-muted-foreground">
          No executions found under <code>./heal-traces/</code>. Run your
          Playwright tests with the heal tracer wired up to populate this
          viewer.
        </div>
      </div>
    );
  }

  if (indexError) {
    return (
      <div className="flex h-full w-full items-center justify-center p-8">
        <div className="max-w-md text-sm text-danger-solid">
          Failed to load trace index: {indexError}
        </div>
      </div>
    );
  }

  if (!currentExecutionId) {
    return null;
  }

  return (
    <MemoryRouter initialEntries={[`/executions/${currentExecutionId}`]}>
      <Tracer
        testList={testList}
        currentTest={currentTest}
        basePath=""
        onParamsChange={setParams}
        features={{ showGroupBy: false }}
        executions={tracerExecutions}
        currentExecutionId={currentExecutionId}
        onExecutionChange={setCurrentExecutionId}
      />
    </MemoryRouter>
  );
};
