import { useContext } from 'react';

import { ExecutionProviderContext } from './execution-provider.context';

export const useExecutionProvider = () => {
  const context = useContext(ExecutionProviderContext);
  if (!context) {
    throw new Error(
      'useExecutionProvider must be used within an ExecutionProvider',
    );
  }

  return context;
};
