import { useCallback, useMemo } from 'react';

import {
  TraceViewerContainer,
  TraceViewerView,
  useTestListPaneConfig,
  type ViewLayout,
} from '../../../../core/ui/features/trace-viewer';
import { useViewProvider } from '../../context/view-provider/view-provider.hooks';
import { HeaderView } from '../views/header/header.view';
import {
  ScreenshotView,
  TEST_SCREENSHOT_VIEW_ID,
} from '../views/screenshot/screenshot.view';
import {
  TEST_CONTENT_VIEW_ID,
  TestContentView,
} from '../views/test-content/test-content.view';
import {
  TEST_LIST_VIEW_ID,
  TestListView,
} from '../views/test-list/test-list.view';
import { VIDEO_VIEW_ID, VideoView } from '../views/video/video.view';

const LAYOUT_STORAGE_KEY = 'runViewer.panelLayout';

const PANE_IDS = [TEST_LIST_VIEW_ID, TEST_CONTENT_VIEW_ID, 'right-panel'];

function getStoredSizes(): number[] | undefined {
  try {
    const raw = localStorage.getItem(LAYOUT_STORAGE_KEY);
    if (!raw) {
      return undefined;
    }

    const layout: ViewLayout = JSON.parse(raw);
    const sizes = PANE_IDS.map((id) => layout.sizes[id]);
    if (sizes.every((s) => typeof s === 'number' && s > 0)) {
      return sizes;
    }
  } catch {
    // ignore corrupted data
  }

  return undefined;
}

export const DefaultMode = () => {
  const { testListVisibility } = useViewProvider();
  const testListPaneConfig = useTestListPaneConfig(testListVisibility.isFolded);

  const defaultSizes = useMemo(() => getStoredSizes(), []);

  const handleLayoutChange = useCallback((layout: ViewLayout) => {
    try {
      localStorage.setItem(LAYOUT_STORAGE_KEY, JSON.stringify(layout));
    } catch {
      // ignore quota errors
    }
  }, []);

  return (
    <>
      <HeaderView />
      <TraceViewerView
        defaultSizes={defaultSizes}
        onLayoutChange={handleLayoutChange}
        panes={[
          {
            id: TEST_LIST_VIEW_ID,
            content: <TestListView />,
            ...testListPaneConfig,
          },
          {
            id: TEST_CONTENT_VIEW_ID,
            content: <TestContentView />,
          },
          {
            id: 'right-panel',
            content: (
              <TraceViewerContainer
                views={[
                  {
                    id: VIDEO_VIEW_ID,
                    label: 'Video',
                    content: <VideoView />,
                  },
                  {
                    id: TEST_SCREENSHOT_VIEW_ID,
                    label: 'Screenshot',
                    content: <ScreenshotView />,
                  },
                ]}
              />
            ),
          },
        ]}
      />
    </>
  );
};
