import { type VerdictResultStatus } from '@heal/front-core/ui';

import { AttemptStatus } from '../types/attempt';

/***
 * Copyright (c) Myia 2023-2026 - All Rights Reserved
 */
export const mapAttemptStatusToVerdict = (
  status?: AttemptStatus | null,
): VerdictResultStatus => {
  if (!status) {
    return 'pending';
  }

  switch (status) {
    case 'passed':
      return 'passed';
    case 'failed':
      return 'failed';
    case 'interrupted':
      return 'failed';
    case 'timedOut':
      return 'failed';
    case 'skipped':
      return 'skipped';
    default:
      return 'skipped';
  }
};
